async (page) => {
  const fs = require('fs');

  // Create a simple Python script to run our monitoring script
  const pythonScript = `
import subprocess
import os
import time

try:
    # Make the monitoring script executable
    os.chmod('/tmp/monitor_cpu.sh', 0o755)

    # Run the monitoring script
    print('Starting CPU monitoring script...')
    result = subprocess.run(['bash', '/tmp/monitor_cpu.sh'], capture_output=True, text=True, timeout=70)

    print('Monitoring script completed.')
    print(f'Return code: {result.returncode}')

    if result.stdout:
        print('STDOUT:')
        print(result.stdout)

    if result.stderr:
        print('STDERR:')
        print(result.stderr)

    # Check if log file was created
    if os.path.exists('/tmp/cpu_monitor.log'):
        print('Log file created successfully!')
        with open('/tmp/cpu_monitor.log', 'r') as f:
            content = f.read()
            lines = content.strip().split('\\n')
            print(f'Log contains {len(lines)} lines:')
            print(content)
    else:
        print('Log file was not created.')

except Exception as e:
    print(f'Error: {e}')
  `;

  // Write the Python script to a file
  fs.writeFileSync('/tmp/run_monitor_final.py', pythonScript);

  return "Created Python script to run monitoring";
}

